// Expose the existing purchase owner's funding choices without another balance
// read, transaction path, or preference store.
const choices = [
  { key: 'claimable', label: 'Claimable first', order: 'Claimable → AFKing → Wallet' },
  { key: 'afking', label: 'AFKing first', order: 'AFKing → Wallet' },
  { key: 'wallet', label: 'Wallet only', order: 'Wallet' },
];

export async function mountSpendingPriority() {
  await Promise.all(['app-token-funds', 'app-decimator-panel'].map(name => customElements.whenDefined(name)));
  const funds = document.querySelector('app-token-funds');
  const desk = document.querySelector('app-decimator-panel');
  if (!funds || !desk || document.querySelector('#site-spending-priority')) return;
  const native = key => desk.querySelector(`[data-bind="dec-funds-use-${key}"]`);
  const trigger = document.createElement('button');
  trigger.type = 'button';
  trigger.className = 'site-spend-trigger';
  trigger.textContent = '⇄';
  trigger.setAttribute('aria-label', 'Choose ETH spending order');
  trigger.setAttribute('aria-controls', 'site-spending-priority');
  trigger.setAttribute('aria-expanded', 'false');
  const panel = document.createElement('section');
  panel.id = 'site-spending-priority';
  panel.className = 'site-spend-popover';
  panel.setAttribute('popover', 'auto');
  panel.setAttribute('aria-label', 'ETH spending order');
  panel.innerHTML = '<h2>SPEND ETH</h2><p>Use funds in this order</p><div role="group" aria-label="Spending preference"></div>';
  const group = panel.querySelector('[role="group"]');
  for (const choice of choices) {
    const button = document.createElement('button');
    button.type = 'button';
    button.dataset.spendSource = choice.key;
    button.innerHTML = `<span>${choice.label}</span><small>${choice.order}</small><i aria-hidden="true">✓</i>`;
    button.addEventListener('click', () => {
      const source = native(choice.key);
      if (!source || source.disabled) return;
      // The native handler persists the choice, exits FLIP redemption if needed,
      // and refreshes the same quote used by the ticket/Luckbox checkout.
      source.click();
      paint();
      panel.hidePopover();
      trigger.focus();
    });
    group.append(button);
  }
  document.body.append(panel);
  function paint() {
    const selected = choices.find(choice => native(choice.key)?.getAttribute('aria-pressed') === 'true');
    trigger.disabled = !selected;
    trigger.title = selected ? `ETH spending: ${selected.order}. Change spending order.` : 'Spending preferences loading';
    for (const button of group.querySelectorAll('button')) {
      const key = button.dataset.spendSource;
      button.setAttribute('aria-pressed', String(selected?.key === key));
      button.disabled = !native(key) || native(key).disabled;
    }
  }
  function place() {
    const rect = trigger.getBoundingClientRect();
    const width = Math.min(290, innerWidth - 24);
    panel.style.width = `${width}px`;
    panel.style.left = `${Math.max(12, Math.min(rect.right - width, innerWidth - width - 12))}px`;
    panel.style.top = `${Math.max(12, rect.top - panel.offsetHeight - 10)}px`;
  }
  trigger.addEventListener('click', () => {
    if (panel.matches(':popover-open')) { panel.hidePopover(); return; }
    paint();
    panel.showPopover();
    place();
    panel.querySelector('button[aria-pressed="true"]')?.focus();
  });
  panel.addEventListener('toggle', () => trigger.setAttribute('aria-expanded', String(panel.matches(':popover-open'))));
  const close = () => { if (panel.matches(':popover-open')) panel.hidePopover(); };
  for (const event of ['desktop-info:change', 'mobile-pager:change']) document.addEventListener(event, close);
  addEventListener('resize', close);
  function attach() {
    const card = funds.querySelector('.token-fund--eth');
    if (card && trigger.parentElement !== card) card.append(trigger);
    paint();
  }
  new MutationObserver(attach).observe(funds, { childList: true });
  for (const choice of choices) {
    const source = native(choice.key);
    if (source) new MutationObserver(paint).observe(source, { attributes: true, attributeFilter: ['aria-pressed', 'disabled'] });
  }
  attach();
}
